CREATE OR REPLACE FUNCTION public.prune_user_events(p_older_than_days integer, p_limit integer DEFAULT 20000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cutoff  timestamptz;
  v_deleted integer;
begin
  -- 90 days is generous for every reader this table has:
  --   recommendation-engine    reads the last 50 events for one visitor
  --   get_trending_entities    reads a 7-day window
  --   get_user_signal          reads a 30-day window
  -- so nothing here is sized by the retention window. The floor guard exists
  -- because that is easy to forget when someone later "tunes" the number.
  if p_older_than_days is null or p_older_than_days < 30 then
    raise exception 'p_older_than_days must be >= 30 (got %) — get_user_signal reads a 30-day window',
      p_older_than_days;
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 200000 then
    raise exception 'p_limit must be between 1 and 200000, got %', p_limit;
  end if;

  v_cutoff := now() - make_interval(days => p_older_than_days);

  with victims as (
    select id from public.user_events
     where created_at < v_cutoff
     order by created_at
     limit p_limit
  )
  delete from public.user_events u
   using victims v
   where u.id = v.id;
  get diagnostics v_deleted = row_count;

  return jsonb_build_object(
    'ok', true,
    'cutoff', v_cutoff,
    'deleted', v_deleted,
    'capped', v_deleted >= p_limit
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.run_marketplace_review_autotriage(p_batch integer DEFAULT 200, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_automation_id uuid; v_run_id bigint; v_enabled boolean;
  v_started timestamptz := now(); v_approved int := 0; v_rejected int := 0;
BEGIN
  SELECT id, enabled INTO v_automation_id, v_enabled
  FROM public.admin_automations WHERE slug = 'marketplace_review_autotriage';

  INSERT INTO public.admin_automation_runs
    (automation_id, automation_slug, started_at, status, items_examined, items_changed)
  VALUES (v_automation_id, 'marketplace_review_autotriage', v_started, 'success', 0, 0)
  RETURNING id INTO v_run_id;

  IF (v_enabled IS DISTINCT FROM true) AND NOT p_force THEN
    UPDATE public.admin_automation_runs SET finished_at=now(),
      summary=jsonb_build_object('skipped',true,'reason','paused') WHERE id=v_run_id;
    UPDATE public.admin_automations SET last_run_at=v_started, last_run_status='paused' WHERE id=v_automation_id;
    RETURN jsonb_build_object('skipped',true,'reason','paused');
  END IF;

  -- Rejections (no listing writes — uncapped).
  WITH cls AS (
    SELECT q.id, q.model, q.proposed_value->>'subcategory' AS proposed, l.subcategory_slug AS cur,
      public.marketplace_content_rating(q.proposed_value->>'subcategory', l.title, l.description) AS wouldbe,
      (lower(coalesce(l.title,'')||' '||coalesce(l.description,'')) ~
       '(latex|wetlook|gummi|rubber|leder|leather|lack|lacquer|pvc|vinyl|fetisch|fetish|harness|ouvert|crotch|nippel|nipple|\mpup\M|puppy|sling|chaps|neopren|bondage|bdsm|dildo|anal|plug|vibrat|cock|penis|keuschheit|chastity|slave|sklav|pinwheel|wartenberg)') AS adult_residual
    FROM public.marketplace_review_queue q JOIN public.marketplace_listings l ON l.id=q.listing_id
    WHERE q.status='open'
  ),
  to_reject AS (
    SELECT id FROM cls
    WHERE (model='extract' AND proposed='Books and Art')
       OR (model='extract' AND proposed='Jewelry and Pins'
           AND cur IN ('sex_toys','anal_toys','cock_rings_and_stretchers','chastity','pumps_and_enlargement','bdsm_and_bondage','fetish_wear'))
       OR (wouldbe NOT IN ('adult','explicit') AND adult_residual)
  )
  UPDATE public.marketplace_review_queue q
  SET status='rejected', reviewed_at=now(),
      reviewer_note='autotriage: rating would cross the 18+ gate with residual adult markers (or extract books/jewelry false positive) — keeping current bucket'
  FROM to_reject t WHERE q.id=t.id;
  GET DIAGNOSTICS v_rejected = ROW_COUNT;

  -- Approvals (listing writes — capped batch protects the search sync).
  WITH cls AS (
    SELECT q.id, q.listing_id, q.created_at, q.proposed_value->>'subcategory' AS proposed,
      public.marketplace_content_rating(q.proposed_value->>'subcategory', l.title, l.description) AS wouldbe,
      (lower(coalesce(l.title,'')||' '||coalesce(l.description,'')) ~
       '(latex|wetlook|gummi|rubber|leder|leather|lack|lacquer|pvc|vinyl|fetisch|fetish|harness|ouvert|crotch|nippel|nipple|\mpup\M|puppy|sling|chaps|neopren|bondage|bdsm|dildo|anal|plug|vibrat|cock|penis|keuschheit|chastity|slave|sklav|pinwheel|wartenberg)') AS adult_residual
    FROM public.marketplace_review_queue q JOIN public.marketplace_listings l ON l.id=q.listing_id
    WHERE q.status='open'
  ),
  batch AS (
    SELECT id, listing_id, proposed FROM cls
    WHERE wouldbe IN ('adult','explicit') OR NOT adult_residual
    ORDER BY created_at
    LIMIT GREATEST(1, LEAST(p_batch, 500))
  ),
  upd AS (
    UPDATE public.marketplace_listings l SET subcategory = b.proposed
    FROM batch b WHERE l.id = b.listing_id RETURNING l.id
  )
  UPDATE public.marketplace_review_queue q
  SET status='approved', reviewed_at=now(),
      reviewer_note='autotriage: applied — post-change rating stays 18+-gated, or text clean of residual adult markers'
  FROM batch b WHERE q.id=b.id;
  GET DIAGNOSTICS v_approved = ROW_COUNT;

  UPDATE public.admin_automation_runs SET finished_at=now(),
    items_examined=v_approved+v_rejected, items_changed=v_approved,
    summary=jsonb_build_object('approved',v_approved,'rejected',v_rejected) WHERE id=v_run_id;
  UPDATE public.admin_automations SET last_run_at=v_started, last_run_status='success' WHERE id=v_automation_id;
  RETURN jsonb_build_object('approved', v_approved, 'rejected', v_rejected);
END; $function$

CREATE OR REPLACE FUNCTION public.run_review_queue_retention(p_max_batches integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total   bigint := 0;
  v_deleted bigint;
  v_batch   int := 0;
BEGIN
  LOOP
    v_batch := v_batch + 1;
    EXIT WHEN v_batch > p_max_batches;

    DELETE FROM review_queue rq WHERE rq.id IN (
      SELECT id FROM review_queue r2
      WHERE r2.status <> 'pending'
         OR r2.created_at < now() - interval '90 days'
         OR (r2.entity_type = 'ingestion_staging' AND NOT EXISTS (
               SELECT 1 FROM ingestion_staging s
               WHERE s.id = r2.entity_id
                 AND s.review_status = 'pending_review'
                 AND s.disposition = 'pending'))
      LIMIT 20000
    );
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    v_total := v_total + v_deleted;
    EXIT WHEN v_deleted < 20000;
  END LOOP;

  RETURN jsonb_build_object('deleted', v_total, 'batches', v_batch);
END;
$function$

CREATE OR REPLACE FUNCTION public.run_staging_rejected_purge(p_batch integer DEFAULT 20000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_automation_id uuid; v_run_id bigint; v_enabled boolean;
  v_started_at timestamptz := now();
  v_total int := 0; v_batch_n int;
BEGIN
  SELECT id, enabled INTO v_automation_id, v_enabled
  FROM public.admin_automations WHERE slug = 'staging_rejected_purge';

  INSERT INTO public.admin_automation_runs
    (automation_id, automation_slug, started_at, status, items_examined, items_changed)
  VALUES (v_automation_id, 'staging_rejected_purge', v_started_at, 'success', 0, 0)
  RETURNING id INTO v_run_id;

  IF v_enabled IS DISTINCT FROM true THEN
    UPDATE public.admin_automation_runs
    SET finished_at = now(), summary = jsonb_build_object('skipped', true, 'reason', 'paused')
    WHERE id = v_run_id;
    UPDATE public.admin_automations SET last_run_at = v_started_at, last_run_status = 'paused'
    WHERE id = v_automation_id;
    RETURN jsonb_build_object('skipped', true, 'reason', 'paused');
  END IF;

  LOOP
    WITH del AS (
      DELETE FROM public.ingestion_staging
      WHERE id IN (
        SELECT id FROM public.ingestion_staging
        WHERE disposition = 'rejected'
          AND created_at < now() - interval '90 days'
        LIMIT least(p_batch, 20000)
      )
      RETURNING 1
    )
    SELECT count(*) INTO v_batch_n FROM del;
    v_total := v_total + v_batch_n;
    EXIT WHEN v_batch_n = 0 OR v_total >= 40000;  -- bound one run's work
  END LOOP;

  UPDATE public.admin_automation_runs
  SET finished_at = now(), items_changed = v_total,
      summary = jsonb_build_object('deleted', v_total, 'threshold_days', 90,
        'rule', 'disposition=rejected AND age>90d -> delete (batched, ≤100k/run)')
  WHERE id = v_run_id;
  UPDATE public.admin_automations SET last_run_at = v_started_at, last_run_status = 'success'
  WHERE id = v_automation_id;

  RETURN jsonb_build_object('deleted', v_total);
EXCEPTION WHEN OTHERS THEN
  UPDATE public.admin_automation_runs
  SET finished_at = now(), status = 'error', error = SQLERRM WHERE id = v_run_id;
  UPDATE public.admin_automations SET last_run_at = v_started_at, last_run_status = 'error'
  WHERE id = v_automation_id;
  RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION api_private.run_existence_signals_purge()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_deleted int := 0; v_batch int;
BEGIN
  PERFORM public.assert_admin_or_internal();
  SET LOCAL statement_timeout = 0;
  LOOP
    WITH ranked AS (
      SELECT id, row_number() OVER (PARTITION BY entity_type, entity_id ORDER BY observed_at DESC) rn
      FROM public.entity_existence_signals
    ), del AS (
      DELETE FROM public.entity_existence_signals s
      USING ranked r
      WHERE s.id=r.id AND r.rn > 20 AND s.observed_at < now() - interval '180 days'
      RETURNING 1
    )
    SELECT count(*) INTO v_batch FROM del;
    v_deleted := v_deleted + v_batch;
    EXIT WHEN v_batch = 0;
  END LOOP;
  RETURN jsonb_build_object('deleted', v_deleted);
END; $function$

CREATE OR REPLACE FUNCTION api_private.run_marketplace_ownership_apply(p_batch integer DEFAULT 300, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_automation_id uuid; v_run_id bigint; v_enabled boolean;
  v_started timestamptz := now(); v_applied int := 0; v_remaining int;
BEGIN
  PERFORM public.assert_admin_or_internal();
  SELECT id, enabled INTO v_automation_id, v_enabled
  FROM public.admin_automations WHERE slug = 'marketplace_ownership_apply';
  INSERT INTO public.admin_automation_runs
    (automation_id, automation_slug, started_at, status, items_examined, items_changed)
  VALUES (v_automation_id, 'marketplace_ownership_apply', v_started, 'success', 0, 0)
  RETURNING id INTO v_run_id;
  IF (v_enabled IS DISTINCT FROM true) AND NOT p_force THEN
    UPDATE public.admin_automation_runs SET finished_at=now(),
      summary=jsonb_build_object('skipped',true,'reason','paused') WHERE id=v_run_id;
    UPDATE public.admin_automations SET last_run_at=v_started, last_run_status='paused' WHERE id=v_automation_id;
    RETURN jsonb_build_object('skipped',true,'reason','paused');
  END IF;
  WITH target AS (
    SELECT l.id, b.ownership_tags AS want
    FROM public.marketplace_listings l
    JOIN public.marketplace_brands b
      ON b.brand_key = public.marketplace_normalize_brand(l.brand)
     AND b.status = 'approved'
    WHERE l.community_owned_tags IS DISTINCT FROM b.ownership_tags
    LIMIT GREATEST(1, LEAST(p_batch, 1000))
  )
  UPDATE public.marketplace_listings l SET community_owned_tags = t.want
  FROM target t WHERE l.id = t.id;
  GET DIAGNOSTICS v_applied = ROW_COUNT;
  SELECT count(*) INTO v_remaining
  FROM public.marketplace_listings l
  JOIN public.marketplace_brands b
    ON b.brand_key = public.marketplace_normalize_brand(l.brand) AND b.status='approved'
  WHERE l.community_owned_tags IS DISTINCT FROM b.ownership_tags;
  UPDATE public.admin_automation_runs SET finished_at=now(),
    items_examined=v_applied+v_remaining, items_changed=v_applied,
    summary=jsonb_build_object('applied',v_applied,'remaining',v_remaining) WHERE id=v_run_id;
  UPDATE public.admin_automations SET last_run_at=v_started, last_run_status='success' WHERE id=v_automation_id;
  RETURN jsonb_build_object('applied', v_applied, 'remaining', v_remaining);
END; $function$
